-- 20261024000000: la lista de Problemas (verificación de evidencia del catálogo) deja de agotar el statement_timeout bajo RLS.
-- Diagnóstico (22-oct, producción, solo lectura): /api/workspace?resource=problems devolvía 503 a los ~15 s. La sentencia activa era la verificación «resumen» de las
-- miles de corridas de cientos de problemas (extraction_runs → message_revisions → messages → conversations → source_heads → tombstones). Sin RLS tarda ~1.9 s; con la política
-- por FILA (`vexa_member(tenant_id)` correlacionado, ~30 µs por fila, ~100 mil filas) ~4.6 s en emulación y >8 s en producción con lectura en frío; con el sub-select no
-- correlacionado (mismo patrón que 0055 y 20261021) ~0.8 s.
-- NO cambia el significado de ninguna política: sigue siendo «tenant de la fila = tenant de la sesión Y la sesión es miembro activa»; solo evalúa la membresía UNA vez por
-- sentencia. ALTER POLICY es atómico (no hay instante sin política). Solo se tocan las 10 políticas del camino de Problemas; las otras ~87 con el mismo patrón quedan igual.
-- Bloqueo: ALTER POLICY toma un candado breve por tabla; lock_timeout hace que falle pronto si otra transacción la sostiene (importaciones activas: aplicar entre cargas).
-- Reversa: packages/workspace-service/tests/20261024000000_problem_path_policies_initplan.down.sql
begin;
set local lock_timeout='3s';
alter policy backend_scope on public.extraction_runs using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid))) with check(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy backend_scope on public.message_revisions using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid))) with check(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy backend_scope on public.messages using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid))) with check(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy backend_scope on public.conversations using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid))) with check(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy backend_scope on public.connections using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid))) with check(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy backend_read on public.source_heads using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy backend_scope on public.tombstones using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid))) with check(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy backend_scope on public.embeddings using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid))) with check(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy members_read on public.problem_embedding_members using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
alter policy backend_scope on public.problem_versions using(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid))) with check(tenant_id=nullif(current_setting('vexa.tenant_id',true),'')::uuid and (select public.vexa_member(nullif(current_setting('vexa.tenant_id',true),'')::uuid)));
commit;
